## 9. 测试 Hooks

### 9.1 使用 renderHook
```typescript
import { renderHook, act } from '@testing-library/react-hooks';

it('应该更新计数 当调用 increment 时', () => {
  const { result } = renderHook(() => useCounter());

  expect(result.current.count).toBe(0);

  act(() => {
    result.current.increment();
  });

  expect(result.current.count).toBe(1);
});
```

## 10. 测试最佳实践

### 10.1 AAA 模式
```typescript
it('应该正确计算总价', () => {
  // Arrange：准备测试数据
  const items = [
    { price: 100, quantity: 2 },
    { price: 50, quantity: 1 },
  ];

  // Act：执行被测试的代码
  const total = calculateTotal(items);

  // Assert：验证结果
  expect(total).toBe(250);
});
```

### 10.2 一个测试一个断言
```typescript
// ✅ 正确：一个测试验证一个行为
it('应该返回正确的用户名', () => {
  const user = getUser(1);
  expect(user.name).toBe('John');
});

it('应该返回正确的用户邮箱', () => {
  const user = getUser(1);
  expect(user.email).toBe('john@example.com');
});

// ❌ 错误：一个测试验证多个行为
it('应该返回正确的用户信息', () => {
  const user = getUser(1);
  expect(user.name).toBe('John');
  expect(user.email).toBe('john@example.com');
  expect(user.age).toBe(25);
});
```

### 10.3 测试边界条件
```typescript
describe('divide', () => {
  it('应该返回正确结果 当除数不为零', () => {
    expect(divide(10, 2)).toBe(5);
  });

  it('应该抛出错误 当除数为零', () => {
    expect(() => divide(10, 0)).toThrow('Division by zero');
  });

  it('应该返回零 当被除数为零', () => {
    expect(divide(0, 10)).toBe(0);
  });
});
```

### 10.4 使用描述性的测试名称
```typescript
// ✅ 正确：描述性强
it('应该返回 null 当用户不存在时', () => {});

// ❌ 错误：描述性弱
it('test1', () => {});
it('works', () => {});
```

## 11. 测试反模式

### 11.1 不要测试实现细节
```typescript
// ❌ 错误：测试实现细节
it('应该设置 state.count 为 1', () => {
  wrapper.setState({ count: 1 });
  expect(wrapper.state('count')).toBe(1);
});

// ✅ 正确：测试公开行为
it('应该显示正确的计数', () => {
  render(<Counter />);
  fireEvent.click(screen.getByText('Increment'));
  expect(screen.getByText('Count: 1')).toBeInTheDocument();
});
```

### 11.2 不要测试私有方法
```typescript
// ❌ 错误：测试私有方法
it('应该调用私有方法', () => {
  const instance = new Service();
  instance['_privateMethod']();
  expect(instance['_called']).toBe(true);
});

// ✅ 正确：通过公开方法测试
it('应该正确执行操作', () => {
  const instance = new Service();
  instance.publicMethod();
  expect(instance.getResult()).toBe('expected');
});
```

### 11.3 不要在测试中包含逻辑
```typescript
// ❌ 错误：测试中包含逻辑
it('复杂测试', () => {
  if (condition) {
    expect(a).toBe(b);
  } else {
    expect(a).toBe(c);
  }
});

// ✅ 正确：简单直接的测试
it('应该返回正确结果 当条件 A', () => {
  const result = service.calculate(10, 20);
  expect(result).toBe(30);
});
```

